package mz.bam.seeky.android;
import android.content.*;import android.database.*;import android.os.*;import android.widget.*;import java.util.*;import org.json.*;

public final class LibraryBatchActivity extends WorkspaceActivity {
    EditText query;LinearLayout entries;TextView selectedLabel;int page;String search="";java.io.File selectionFile;final Set<String> selected=new LinkedHashSet<>();
    String title(){return "Editar livros em lote";}
    void load(){if(query==null){query=PlusUi.input(this,"Título, autor ou nome","",200);content.addView(query);action("Pesquisar",()->{search=query.getText().toString();page=0;load();});selectedLabel=label("0",12);content.addView(selectedLabel);action("Seleccionar todos os resultados",this::all);action("Limpar selecção",()->{selected.clear();load();});action("Editar seleccionados",this::edit);entries=PlusUi.column(this);content.addView(entries);}
        final BookQuery filter=new BookQuery(search,7,0,0,false,Collections.emptySet());final int offset=page*30;PlusUi.run(this,()->{List<StudyStore.Row> rows;long total;try(StudyStore db=new StudyStore(this)){rows=db.page("materials",filter.where,filter.args,filter.order,30,offset);total=db.count("materials",filter.where,filter.args);}PlusUi.post(this,()->{entries.removeAllViews();selectedLabel.setText(selected.size()+" "+AppLanguage.text(this,"seleccionados"));entries.addView(label((offset+1)+"–"+Math.min(total,offset+rows.size())+" / "+total,12));for(StudyStore.Row r:rows){CheckBox b=new CheckBox(this);b.setText(r.s("title")+(r.s("author").isEmpty()?"":"\n"+r.s("author")));b.setTextColor(colors.ink);b.setMinHeight(dp(62));b.setChecked(selected.contains(r.s("hash")));b.setOnCheckedChangeListener((v,on)->{if(on)selected.add(r.s("hash"));else selected.remove(r.s("hash"));selectedLabel.setText(selected.size()+" "+AppLanguage.text(this,"seleccionados"));});entries.addView(b);}LinearLayout nav=new LinearLayout(this);if(page>0){TextView b=label("Anterior",14);UiBox.style(b);b.setOnClickListener(v->{page--;load();});nav.addView(b,new LinearLayout.LayoutParams(0,-2,1));}if(offset+rows.size()<total){TextView b=label("Seguinte",14);UiBox.style(b);b.setOnClickListener(v->{page++;load();});nav.addView(b,new LinearLayout.LayoutParams(0,-2,1));}entries.addView(nav);});});}
    void all(){BookQuery filter=new BookQuery(search,7,0,0,false,Collections.emptySet());PlusUi.run(this,()->{List<String> hashes=new ArrayList<>();try(StudyStore db=new StudyStore(this);Cursor c=db.getReadableDatabase().query("materials",new String[]{"hash"},filter.where,filter.args,null,null,"id")){while(c.moveToNext())hashes.add(c.getString(0));}PlusUi.post(this,()->{selected.addAll(hashes);load();});});}
    void edit(){if(selected.isEmpty()){PlusUi.toast(this,"Escolha pelo menos um livro.");return;}LinearLayout form=PlusUi.column(this);CheckBox setAuthor=new CheckBox(this),setSeries=new CheckBox(this),setTopic=new CheckBox(this);setAuthor.setText(AppLanguage.text(this,"Aplicar autor"));setSeries.setText(AppLanguage.text(this,"Aplicar série"));setTopic.setText(AppLanguage.text(this,"Aplicar assunto"));EditText author=PlusUi.input(this,"Autor","",200),series=PlusUi.input(this,"Série","",120),topic=PlusUi.input(this,"Assunto","",120),prefix=PlusUi.input(this,"Prefixo do título (opcional)","",80);for(android.view.View v:new android.view.View[]{setAuthor,author,setSeries,series,setTopic,topic,prefix})form.addView(v);new UiDialog.Builder(this).setTitle("Editar "+selected.size()+" livros").setView(form).setPositiveButton("Aplicar",(d,w)->{try{JSONObject data=new JSONObject().put("author_set",setAuthor.isChecked()).put("author",author.getText().toString().trim()).put("series_set",setSeries.isChecked()).put("series",series.getText().toString().trim()).put("topic_set",setTopic.isChecked()).put("topic",topic.getText().toString().trim()).put("prefix",prefix.getText().toString().trim());Set<String> hashes=new LinkedHashSet<>(selected);PlusUi.run(this,()->{String id;try(TaskStore tasks=new TaskStore(this);StudyStore books=new StudyStore(this)){id=tasks.create("metadata","Editar metadados de livros",data);int n=0;for(String hash:hashes){List<StudyStore.Row> rows=books.rows("materials","hash=?",new String[]{hash},"id",1);if(!rows.isEmpty())tasks.add(id,n++,hash,rows.get(0).s("title"),0,0);}tasks.totals(id);}final String job=id;TaskService.launch(this,job);});}catch(Exception e){PlusUi.error(this,e);}}).setNegativeButton("Cancelar",null).show();}
    public void onCreate(Bundle state){if(state!=null){String name=state.getString("selection_file","");if(name.matches("book-selection-[a-f0-9-]+\\.txt"))try{selectionFile=new java.io.File(getCacheDir(),name);try(java.io.BufferedReader reader=new java.io.BufferedReader(new java.io.FileReader(selectionFile))){for(String line;(line=reader.readLine())!=null;)if(line.matches("[a-f0-9]{64}"))selected.add(line);}}catch(java.io.IOException ignored){}}super.onCreate(state);}
    protected void onSaveInstanceState(Bundle out){try{if(selectionFile==null)selectionFile=new java.io.File(getCacheDir(),"book-selection-"+java.util.UUID.randomUUID()+".txt");try(java.io.Writer writer=new java.io.BufferedWriter(new java.io.FileWriter(selectionFile))){for(String hash:selected)writer.write(hash+"\n");}out.putString("selection_file",selectionFile.getName());}catch(java.io.IOException e){AppDiagnostics.record(this,"selection-state",e);}super.onSaveInstanceState(out);}
    protected void onDestroy(){if(isFinishing()&&selectionFile!=null)selectionFile.delete();super.onDestroy();}
}
